    return {
      showCreateTeam: false,
      showCreateChannel: false,
      showTeamSettings: false,
      showAddMember: false,
      createChannelCategoryId: null,
      editingChannel: null,
      editingChannelCategory: null,
      editingCategory: null,
      selectedMember: null,
      isTeamBarCollapsed: false,
      isQuickBarCollapsed: false
    }
